import styles from "../Profile.module.css";

const ProfileStatCard = ({ title, value }) => {
  return (
    <div className={styles.statCard}>
      <h4>{title}</h4>
      <p className={styles.statValue}>{value}</p>
    </div>
  );
};

export default ProfileStatCard;
